/**
 * 将二阶贝塞尔曲线等距分割。
 * @param {number} p1x 起点x
 * @param {number} p1y 起点y
 * @param {number} ptx 控制点x
 * @param {number} pty 控制点y
 * @param {number} p2x 终点x
 * @param {number} p2y 终点y
 * @param space - 指定的点之间的距离。
 * @returns 分割点的坐标数组。
 */
export declare const getEquidistantBezierPoints: (p1x: number, p1y: number, ptx: number, pty: number, p2x: number, p2y: number, space: number) => {
    x: number;
    y: number;
}[];
/**
 * 计算二次贝塞尔曲线的近似长度。
 * @param {number} p1x 起点x
 * @param {number} p1y 起点y
 * @param {number} ptx 控制点x
 * @param {number} pty 控制点y
 * @param {number} p2x 终点x
 * @param {number} p2y 终点y
 * @param numSegments - 精度，即曲线被分成多少段来近似计算长度，值越大计算结果越精确，但计算量也越大。
 * @returns 二次贝塞尔曲线的近似长度。
 */
export declare const getQuadraticBezierDistance: (p1x: number, p1y: number, ptx: number, pty: number, p2x: number, p2y: number, numSegments?: number) => number;
/**
 * 二次贝塞尔计算
 * @param {number} t 0-1 点位于线段中的位置
 * @param {number} p1x 起点x
 * @param {number} p1y 起点y
 * @param {number} ptx 控制点x
 * @param {number} pty 控制点y
 * @param {number} p2x 终点x
 * @param {number} p2y 终点y
 * @returns
 */
export declare const quadraticBezier: (t: number, p1x: number, p1y: number, ptx: number, pty: number, p2x: number, p2y: number) => {
    x: number;
    y: number;
};
/**
 * 获取两点之间贝塞尔控制点(一个)
 *
 * @param {number} p1x 终点x
 * @param {number} p1y 终点y
 * @param {number} p2x 起点x
 * @param {number} p2y 起点y
 * @param {number} p3x 起点前一个点x
 * @param {number} p3y 起点前一个点y
 * @param {number} ratio 0-1 默认0.25
 * @returns
 */
export declare const getControlPoint: (p1x: number, p1y: number, p2x: number, p2y: number, p3x: number, p3y: number, ratio?: number) => {
    x: number;
    y: number;
};
/**
 * 获取两点之间贝塞尔控制点(共两个)
 *
 * @param {number} p1x 终点x
 * @param {number} p1y 终点y
 * @param {number} p2x 起点x
 * @param {number} p2y 起点y
 * @param {number} p3x 起点前一个点x
 * @param {number} p3y 起点前一个点y
 * @param {number} ratio 0-1 默认0.25
 * @returns
 */
export declare const getAllControlPoint: (p1x: number, p1y: number, p2x: number, p2y: number, p3x: number, p3y: number, ratio?: number) => {
    x: number;
    y: number;
}[];
/**
 * 使用二分法找到对应于给定弧长的参数t值。
 * @param {number} p1x 起点x
 * @param {number} p1y 起点y
 * @param {number} ptx 控制点x
 * @param {number} pty 控制点y
 * @param {number} p2x 终点x
 * @param {number} p2y 终点y
 * @param targetLength - 目标弧长。
 * @param tolerance - 容差。
 * @returns 对应于给定弧长的参数t值。
 */
export declare const findTForLength: (p1x: number, p1y: number, ptx: number, pty: number, p2x: number, p2y: number, targetLength: number, tolerance?: number) => number;
